          'late':9,'early_finish':10,'runtime_failure':11,'freeze':12,'after4':13,
          'compile_error':0,'x_decrypt_busy':14}

def digest(path):
    b=path.read_bytes()
    return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    mode=ap.add_mutually_exclusive_group()
    mode.add_argument('--fixture',choices=FAULTS)
    mode.add_argument('--dut',nargs='+',help='Explicit self-contained HDL sources including protocol_dut adapter, within restart root')
    ap.add_argument('--dut-origin',help='Recorded original-source provenance for supplied DUT (not independently authenticated)')
    ap.add_argument('--timing',choices=['report','launch-inclusive-4','after-launch-4'],default='report')
    ap.add_argument('--led-unavailable',action='store_true',help='Adapter drives ICE_LED=x; mark check unavailable, never pass')
    ap.add_argument('--compiler',default='iverilog')
    ap.add_argument('--runtime',default='vvp')
    ap.add_argument('--timeout',type=float,default=10,help='Harness wall timeout per tool; not a target protocol deadline')
    a=ap.parse_args()
    run=BASE/'runs'/(datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')+'_'+uuid.uuid4().hex[:8])
    run.mkdir(parents=True)
    (run/'sources').mkdir()
    (run/'sources/runner.py').write_bytes(Path(__file__).read_bytes())
    (run/'sources/acceptance.py').write_bytes((BASE/'tests/acceptance.py').read_bytes())
    result={'status':'STARTED','kind':'fixture' if a.fixture else 'dut',
            'target_correctness':'UNESTABLISHED','target_checks':'NOT_RUN',
            'timing_conformance':'UNRESOLVED','checks':{},'run_directory':str(run),
            'fixture':a.fixture,'dut_origin':a.dut_origin,'timing_policy':a.timing,
            'source_commit':PIN,'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
    commands=[]
    def save(status,code,detail=None):
        result['status']=status
        if detail is not None: result['detail']=detail
        result['finished_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
        (run/'result.json').write_text(json.dumps(result,indent=2)+'\n')
        (run/'commands.json').write_text(json.dumps(commands,indent=2)+'\n')
        hashes={str(p.relative_to(run)):digest(p) for p in sorted(run.rglob('*')) if p.is_file() and p.name!='output_hashes.json'}
        (run/'output_hashes.json').write_text(json.dumps(hashes,indent=2)+'\n')
        print(json.dumps(result))
        return code
    def command(argv,label):
        entry={'argv':argv,'cwd':str(run),'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
        commands.append(entry)
        try:
            p=subprocess.run(argv,cwd=run,capture_output=True,text=True,timeout=a.timeout)
            entry['returncode']=p.returncode
            stdout,stderr=p.stdout,p.stderr
        except subprocess.TimeoutExpired as e:
            stdout=e.stdout or b''; stderr=e.stderr or b''
            if isinstance(stdout,bytes): stdout=stdout.decode(errors='replace')
            if isinstance(stderr,bytes): stderr=stderr.decode(errors='replace')
            entry['timeout']=True
            p=None
        (run/(label+'.stdout.txt')).write_text(stdout)
        (run/(label+'.stderr.txt')).write_text(stderr)
        entry['finished_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
        return p,stdout
    if a.timeout<=0:
        return save('INVALID_INPUT',2,'timeout must be positive')
    # N01: re-read original bytes; never import or execute original host code.
    try:
        rp=ROOT/'original_materials/SOURCE_RECEIPT.json'
        receipt=json.loads(rp.read_text())
        assert receipt['selected_commit']==PIN and len(receipt['files'])==6
        verified=[]
        for f in receipt['files']:
            p=(ROOT/'original_materials'/f['path']).resolve()
            assert p.is_relative_to(ROOT/'original_materials')
            b=p.read_bytes()
            actual={**digest(p),'source_git_blob_id':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()}
            assert all(actual[k]==f[k] for k in actual),f['path']
            verified.append({'path':f['path'],**actual,'status':'PASS'})
        (run/'original_verification.json').write_text(json.dumps({'receipt':digest(rp),'files':verified},indent=2)+'\n')
        result['checks']['N01']='PASS'
    except (OSError,ValueError,KeyError,AssertionError) as e:
        result['checks']['N01']='FAIL'
        return save('SOURCE_VERIFICATION_FAILED',2,str(e))
    if not a.fixture and not a.dut:
        return save('MISSING_DUT',2,'No target supplied; no fixture fallback. Target checks NOT_RUN.')
    if a.dut and not a.dut_origin:
        return save('MISSING_DUT_ORIGIN',2,'Record original-source origin explicitly.')
    inputs=[BASE/'tb/protocol_tb.sv']
    if a.fixture:
        inputs.append(BASE/'fixtures'/('compile_error.sv' if a.fixture=='compile_error' else 'harness_fixture.sv'))
    else:
        for filename in a.dut:
            p=Path(filename).resolve()
            if not p.is_relative_to(ROOT) or p.is_relative_to(BASE/'fixtures') or not p.is_file():
                return save('INVALID_DUT_INPUT',2,'DUT must be an existing explicit source inside restart root, outside fixtures.')
            if p.suffix not in ('.v','.sv'):
                return save('INVALID_DUT_INPUT',2,'Only explicit HDL sources accepted.')
            inputs.append(p)
    snapshots=[]; identities=[]
    for i,p in enumerate(inputs):
        # Sources must be self-contained: no unlogged include/memory-file dependencies.
        b=p.read_bytes()
        if not a.fixture and p!=inputs[0] and re.search(rb'`include|\$readmem[hb]',b):
            return save('INVALID_DUT_INPUT',2,'Supply self-contained HDL; includes/readmem dependencies are not captured.')
        dest=run/'sources'/(str(i)+'_'+p.name); dest.write_bytes(b)
        snapshots.append(str(dest)); identities.append({'origin_path':str(p),'snapshot':str(dest.relative_to(run)),**digest(dest)})
    (run/'source_identities.json').write_text(json.dumps(identities,indent=2)+'\n')
    versions={'python':sys.version,'platform':platform.platform(),'serving_model':'Exact identifier unavailable; system describes GPT-6-based assistant'}
    try:
        for tool,label in [(a.compiler,'compiler_version'),(a.runtime,'runtime_version')]:
            p,_=command([tool,'-V'],label)
            if p is None or p.returncode!=0:
                return save('TOOL_UNAVAILABLE',3,label)
            versions[label]={'stdout_file':label+'.stdout.txt','stderr_file':label+'.stderr.txt'}
    except OSError as e:
        return save('TOOL_UNAVAILABLE',3,str(e))
    (run/'versions.json').write_text(json.dumps(versions,indent=2)+'\n')
    compile_cmd=[a.compiler,'-g2012','-Wall','-s','protocol_tb','-o',str(run/'sim.vvp')]
    if a.fixture: compile_cmd.append('-DFAULT='+str(FAULTS[a.fixture]))
    compile_cmd.extend(snapshots)
    try:
        p,_=command(compile_cmd,'compile')
        if p is None or p.returncode!=0: return save('COMPILE_FAILED',3)
        p,stdout=command([a.runtime,'-n',str(run/'sim.vvp'),'+timing='+str(['report','launch-inclusive-4','after-launch-4'].index(a.timing)),'+led='+str(int(not a.led_unavailable))],'simulate')
    except OSError as e:
        return save('TOOL_UNAVAILABLE',3,str(e))
    # FAIL always dominates repeated samples, including final LED pass marker.
    observations={}
    for key,status in re.findall(r'^CHECK (N\d+) (PASS|FAIL|UNRESOLVED|UNAVAILABLE|STIMULUS_APPLIED|BLOCKED)$',stdout,re.M):
        observations.setdefault(key,[]).append(status)
    for key,states in observations.items():
        result['checks'][key]='FAIL' if 'FAIL' in states else states[-1]
    (run/'check_observations.json').write_text(json.dumps(observations,indent=2)+'\n')
    if not a.fixture: result['target_checks']='ATTEMPTED_LIMITED_SOURCE_VECTOR_ONLY'
    if p is None: return save('SIMULATION_TIMEOUT',4)
    if p.returncode!=0 or 'FAIL' in result['checks'].values(): return save('SIMULATION_FAILED',4)
    markers=re.findall(r'^HARNESS_COMPLETE failures=(\d+)$',stdout,re.M)
    required=['N02','N03','N04','N05','N06','N07','N08','N09','N10','N11','N12']
    if markers!=['0'] or not all(k in observations for k in required):
        return save('INCOMPLETE_SIMULATION',4,'Clean process exit is insufficient; full check markers required.')
    expected={'N02':'PASS','N03':'STIMULUS_APPLIED','N04':'PASS','N05':'PASS','N06':'UNRESOLVED' if a.timing=='report' else 'PASS','N07':'PASS','N08':'PASS','N09':'STIMULUS_APPLIED','N10':'PASS','N11':'PASS','N12':'UNAVAILABLE' if a.led_unavailable else 'PASS'}
    if any(result['checks'].get(k)!=v for k,v in expected.items()):
        return save('INCOMPLETE_SIMULATION',4,'Unexpected or missing check status.')
    result['timing_conformance']='UNRESOLVED' if a.timing=='report' else 'EXPLICIT_POLICY_PASSED_NOT_AUTHORITATIVE'
    result['checks']['N13']='LIMITED_CHECKS_ONLY_UNESTABLISHED'
    if a.fixture: return save('HARNESS_ONLY_PASS',0,'Canned fixture exercises infrastructure only. No target was run.')
    return save('SOURCE_VECTOR_CHECKS_PASSED_WITH_OPEN_REQUIREMENTS',0,'Not full target correctness; unresolved timing, algorithm and coverage remain.')

if __name__=='__main__':
    sys.exit(main())
